    totalMismatch += mismatch;
    console.log(`${domain.toUpperCase()}:`);
    console.log(`  OLD COUNT: ${oldVal}`);
    console.log(`  NEW COUNT: ${newVal}`);
    console.log(`  MISMATCH : ${mismatch === 0 ? "0 (\u2713 MATCHED)" : mismatch + " (\u274C MISMATCH)"}`);
