router4.get("/activity-logs", auth2, (req, res) => {
  try {
    const { action, search, from, to, limit: limit2 = 300 } = req.query;
    let query2 = "SELECT * FROM audit_logs";
    const conditions = [];
    const params = [];
    if (action && action !== "all") {
      const actStr = String(action).toLowerCase();
      if (actStr === "create") {
        conditions.push("(action LIKE '%CREATE%' OR action LIKE '%T\u1EA1o%')");
      } else if (actStr === "update") {
        conditions.push("(action LIKE '%UPDATE%' OR action LIKE '%C\u1EADp nh\u1EADt%' OR action LIKE '%S\u1EEDa%')");
      } else if (actStr === "delete") {
        conditions.push("(action LIKE '%DELETE%' OR action LIKE '%X\xF3a%')");
      } else if (actStr === "restore") {
        conditions.push("(action LIKE '%RESTORE%' OR action LIKE '%Kh\xF4i ph\u1EE5c%')");
      } else {
        conditions.push("action = ?");
        params.push(action);
      }
    }
    if (search && typeof search === "string" && search.trim()) {
      const term = `%${search.trim()}%`;
      conditions.push("(user LIKE ? OR action LIKE ? OR entityId LIKE ? OR performedBy LIKE ? OR reason LIKE ? OR details LIKE ?)");
      params.push(term, term, term, term, term, term);
    }
    if (from) {
      conditions.push("(performedAt >= ? OR time >= ?)");
      params.push(String(from), String(from));
    }
    if (to) {
      conditions.push("(performedAt <= ? OR time <= ?)");
      params.push(String(to), String(to));
    }
    if (conditions.length > 0) {
      query2 += " WHERE " + conditions.join(" AND ");
    }
    query2 += " ORDER BY rowid DESC LIMIT ?";
    params.push(Math.min(Number(limit2) || 300, 1e3));
    const rows = database_default.prepare(query2).all(...params);
    let userRoleMap = {};
    try {
      const userRows = database_default.prepare("SELECT username, name, role FROM users").all();
      userRows.forEach((u) => {
        if (u.name) userRoleMap[u.name.toLowerCase()] = u.role;
        if (u.username) userRoleMap[u.username.toLowerCase()] = u.role;
      });
    } catch (e) {
    }
    const formattedLogs = rows.map((r) => {
      let parsedDetails = {};
      if (r.details) {
        try {
          parsedDetails = typeof r.details === "string" ? JSON.parse(r.details) : r.details;
        } catch (e) {
          parsedDetails = { raw: r.details };
        }
      }
      const userName = r.user || r.performedBy || "Qu\u1EA3n tr\u1ECB vi\xEAn";
      const userRole = userRoleMap[userName.toLowerCase()] || (userName.toLowerCase().includes("admin") || userName.toLowerCase().includes("gi\xE1m \u0111\u1ED1c") ? "admin" : "staff");
      return {
        id: r.id,
        user: userName,
        performedBy: r.performedBy || userName,
        role: userRole,
        action: r.action,
        entityType: r.entityType || "erp_records",
        entityId: r.entityId || parsedDetails?.id || parsedDetails?.contractId || "",
        performedAt: r.performedAt || r.time || (/* @__PURE__ */ new Date()).toISOString(),
        time: r.time || r.performedAt || (/* @__PURE__ */ new Date()).toISOString(),
        reason: r.reason || "",
        result: r.result || "SUCCESS",
        details: parsedDetails
      };
    });
    const totalCount = database_default.prepare("SELECT COUNT(*) as count FROM audit_logs").get();
    const createCount = database_default.prepare("SELECT COUNT(*) as count FROM audit_logs WHERE action LIKE '%CREATE%'").get();
    const updateCount = database_default.prepare("SELECT COUNT(*) as count FROM audit_logs WHERE action LIKE '%UPDATE%'").get();
    const deleteCount = database_default.prepare("SELECT COUNT(*) as count FROM audit_logs WHERE action LIKE '%DELETE%'").get();
    const restoreCount = database_default.prepare("SELECT COUNT(*) as count FROM audit_logs WHERE action LIKE '%RESTORE%'").get();
    res.json({
      success: true,
      data: formattedLogs,
      metrics: {
        total: totalCount?.count || formattedLogs.length,
        creations: createCount?.count || 0,
        modifications: updateCount?.count || 0,
        deletions: deleteCount?.count || 0,
        restorations: restoreCount?.count || 0
      }
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});
