router4.get("/cases/next-code", auth2, (req, res) => {
  try {
    const currentYear = (/* @__PURE__ */ new Date()).getFullYear();
    const caseType = req.query.caseType || "H\xECnh s\u1EF1";
    let prefix = "HD";
    const typeText = String(caseType).trim();
    if (typeText.includes("H\xECnh s\u1EF1")) {
      prefix = "HS";
    } else if (typeText.includes("D\xE2n s\u1EF1")) {
      prefix = "DS";
    } else if (typeText.includes("H\xE0nh ch\xEDnh")) {
      prefix = "HC";
    } else if (typeText.includes("T\u01B0 v\u0103n") || typeText.includes("T\u01B0 v\u1EA5n")) {
      prefix = "TV";
    } else if (typeText.includes("Doanh nghi\u1EC7p") || typeText.includes("\u0110\u1EA7u t\u01B0")) {
      prefix = "DN";
    } else if (typeText.includes("H\xF4n nh\xE2n") || typeText.includes("Gia \u0111\xECnh")) {
      prefix = "HN";
    } else if (typeText.includes("Th\u1EEBa k\u1EBF") || typeText.includes("Di ch\xFAc")) {
      prefix = "TK";
    } else if (typeText.includes("S\u1EDF h\u1EEFu tr\xED tu\u1EC7") || typeText.includes("Nh\xE3n hi\u1EC7u")) {
      prefix = "SHTT";
    } else if (typeText.includes("Lao \u0111\u1ED9ng")) {
      prefix = "L\u0110";
    } else if (typeText.includes("Th\u01B0\u01A1ng m\u1EA1i qu\u1ED1c t\u1EBF")) {
      prefix = "TMQT";
    } else if (typeText.includes("Tr\u1ECDng t\xE0i") || typeText.includes("H\xF2a gi\u1EA3i")) {
      prefix = "TA";
    } else if (typeText.includes("Ph\xE1p ch\u1EBF") || typeText.includes("N\u1ED9i b\u1ED9")) {
      prefix = "PC";
    } else if (typeText.includes("\u0110\u1EA1i di\u1EC7n")) {
      prefix = "DD";
    }
    const lookupPattern = `${prefix}-${currentYear}-%`;
    const lastCase = database_default.prepare(`
      SELECT id 
      FROM cases 
      WHERE id LIKE ? 
      ORDER BY id DESC 
      LIMIT 1
    `).get(lookupPattern);
    let nextNumber = 1;
    if (lastCase && lastCase.id) {
      const parts = lastCase.id.split("-");
      if (parts.length === 3) {
        const lastNumber = parseInt(parts[2], 10);
        if (!isNaN(lastNumber)) {
          nextNumber = lastNumber + 1;
        }
      }
    }
    const paddedNumber = String(nextNumber).padStart(3, "0");
    const nextGeneratedCode = `${prefix}-${currentYear}-${paddedNumber}`;
    res.json({ success: true, caseCode: nextGeneratedCode });
  } catch (error) {
    console.error("L\u1ED7i t\u1EF1 sinh m\xE3 h\u1ED3 s\u01A1:", error.message);
    res.status(500).json({ success: false, error: "Kh\xF4ng th\u1EC3 kh\u1EDFi t\u1EA1o m\xE3 h\u1ED3 s\u01A1 t\u1EF1 \u0111\u1ED9ng t\u1EEB h\u1EC7 th\u1ED1ng: " + error.message });
  }
});
