function calculateImportanceScore(title, content, memoryType) {
  let score = 0.5;
  const text = `${title} ${content}`.toLowerCase();
  const highKeywords = [
    "kh\u1EA9n c\u1EA5p",
    "t\u1ED1i m\u1EADt",
    "b\u1EAFt bu\u1ED9c",
    "lu\xF4n lu\xF4n",
    "kh\xF4ng bao gi\u1EDD",
    "th\u1EDDi hi\u1EC7u",
    "kh\u1EDFi ki\u1EC7n",
    "\xE1n ph\xED",
    "ngh\u1ECB \u0111\u1ECBnh",
    "\u0111i\u1EC1u lu\u1EADt",
    "b\u1EA3n \xE1n",
    "\u01B0u ti\xEAn cao",
    "ch\xFA \xFD \u0111\u1EB7c bi\u1EC7t",
    "th\u1ECFa thu\u1EADn k\xEDn"
  ];
  const mediumKeywords = [
    "th\xF3i quen",
    "s\u1EDF th\xEDch",
    "y\xEAu c\u1EA7u",
    "\u0111\u1ECBnh d\u1EA1ng",
    "h\u1EA1n ch\xF3t",
    "ti\u1EBFn \u0111\u1ED9",
    "li\xEAn h\u1EC7",
    "chi nh\xE1nh"
  ];
  for (const kw of highKeywords) {
    if (text.includes(kw)) score += 0.15;
  }
  for (const kw of mediumKeywords) {
    if (text.includes(kw)) score += 0.08;
  }
  if (memoryType === "user_preference" || memoryType === "case_insight") {
    score += 0.1;
  }
  return Math.min(1, Math.max(0.1, parseFloat(score.toFixed(2))));
}
