var AgentMemoryService = class {
  /**
   * Store or update an AI Memory item
   */
  static storeMemory(item) {
    try {
      const now = (/* @__PURE__ */ new Date()).toISOString();
      const importance = item.importance_score ?? calculateImportanceScore(item.title, item.content, item.memory_type);
      const confidence = item.confidence_score ?? 0.85;
      const tagsJson = JSON.stringify(item.tags || []);
      const metaJson = JSON.stringify(item.metadata || {});
      const existing = database_default.prepare(`
        SELECT id, content, access_count, tags, metadata 
        FROM ai_agent_memories 
        WHERE (title = ? OR (entity_id = ? AND entity_type = ? AND title LIKE ?))
          AND status = 'active'
        LIMIT 1
      `).get(item.title, item.entity_id || "NONE", item.entity_type || "NONE", `%${item.title.slice(0, 15)}%`);
      if (existing) {
        database_default.prepare(`
          UPDATE ai_agent_memories SET
            content = ?,
            summary = ?,
            importance_score = MAX(importance_score, ?),
            confidence_score = ?,
            access_count = access_count + 1,
            last_accessed_at = ?,
            tags = ?,
            metadata = ?,
            updated_at = ?
          WHERE id = ?
        `).run(
          item.content,
          item.summary || item.title,
          importance,
          confidence,
          now,
          tagsJson,
          metaJson,
          now,
          existing.id
        );
        return {
          success: true,
          id: existing.id,
          message: `\u0110\xE3 h\u1EE3p nh\u1EA5t v\xE0 c\u1EADp nh\u1EADt k\xFD \u1EE9c hi\u1EC7n h\u1EEFu ID #${existing.id}.`
        };
      }
      const stmt = database_default.prepare(`
        INSERT INTO ai_agent_memories (
          user_email, memory_type, category, title, content, summary,
          entity_type, entity_id, importance_score, confidence_score,
          access_count, last_accessed_at, status, source_session, tags, metadata, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, 'active', ?, ?, ?, ?, ?)
      `);
      const result = stmt.run(
        item.user_email || "system",
        item.memory_type || "semantic",
        item.category || "general",
        item.title,
        item.content,
        item.summary || item.title,
        item.entity_type || "SYSTEM",
        item.entity_id || null,
        importance,
        confidence,
        now,
        item.source_session || null,
        tagsJson,
        metaJson,
        now,
        now
      );
      return {
        success: true,
        id: Number(result.lastInsertRowid),
        message: `\u0110\xE3 l\u01B0u k\xFD \u1EE9c m\u1EDBi v\xE0o Memory Store th\xE0nh c\xF4ng.`
      };
    } catch (err) {
      console.error("Error storing agent memory:", err);
      throw new Error(err.message || "Failed to store memory.");
    }
  }
  /**
   * Recall / Search Memories with Cognitive Scoring (Similarity + Importance + Recency Decay)
   */
  static recallMemories(options) {
    try {
      const {
        query: query2,
        user_email,
        entity_type,
        entity_id,
        category,
        memory_types,
        limit: limit2 = 6,
        min_score = 0.25
      } = options;
      let sql = `SELECT * FROM ai_agent_memories WHERE status = 'active'`;
      const params = [];
      if (user_email && user_email !== "all") {
        sql += ` AND (user_email = ? OR user_email = 'system')`;
        params.push(user_email);
      }
      if (entity_type) {
        sql += ` AND entity_type = ?`;
        params.push(entity_type);
      }
      if (entity_id) {
        sql += ` AND entity_id = ?`;
        params.push(entity_id);
      }
      if (category) {
        sql += ` AND category = ?`;
        params.push(category);
      }
      if (memory_types && memory_types.length > 0) {
        const placeholders = memory_types.map(() => "?").join(",");
        sql += ` AND memory_type IN (${placeholders})`;
        params.push(...memory_types);
      }
      const rows = database_default.prepare(sql).all(...params);
      if (!rows || rows.length === 0) return [];
      const nowTime = Date.now();
      const queryTokens = query2.toLowerCase().split(/\s+/).filter((t) => t.length > 1);
      const scored = rows.map((row) => {
        const text = `${row.title} ${row.content} ${row.summary || ""} ${row.tags || ""}`.toLowerCase();
        let matchCount = 0;
        for (const token of queryTokens) {
          if (text.includes(token)) {
            matchCount++;
          }
        }
        const relevanceScore = queryTokens.length > 0 ? matchCount / queryTokens.length : 0.5;
        const importanceScore = row.importance_score || 0.5;
        const itemTime = row.updated_at ? new Date(row.updated_at).getTime() : nowTime;
        const diffDays = Math.max(0, (nowTime - itemTime) / (1e3 * 60 * 60 * 24));
        const recencyScore = Math.exp(-0.05 * diffDays);
        const accessBoost = Math.min(0.2, (row.access_count || 0) * 0.02);
        const finalScore = parseFloat((relevanceScore * 0.5 + importanceScore * 0.3 + recencyScore * 0.15 + accessBoost * 0.05).toFixed(3));
        return {
          memory: {
            id: row.id,
            user_email: row.user_email,
            memory_type: row.memory_type,
            category: row.category,
            title: row.title,
            content: row.content,
            summary: row.summary,
            entity_type: row.entity_type,
            entity_id: row.entity_id,
            importance_score: row.importance_score,
            confidence_score: row.confidence_score,
            access_count: row.access_count,
            last_accessed_at: row.last_accessed_at,
            status: row.status,
            tags: JSON.parse(row.tags || "[]"),
            metadata: JSON.parse(row.metadata || "{}"),
            created_at: row.created_at,
            updated_at: row.updated_at
          },
          score: finalScore,
          relevanceScore: parseFloat(relevanceScore.toFixed(2)),
          importanceScore: parseFloat(importanceScore.toFixed(2)),
          recencyScore: parseFloat(recencyScore.toFixed(2))
        };
      });
      const results = scored.filter((s) => s.score >= min_score || options.query === "" && s.importanceScore > 0.6).sort((a, b) => b.score - a.score).slice(0, limit2);
      if (results.length > 0) {
        const ids = results.map((r) => r.memory.id).filter(Boolean);
        if (ids.length > 0) {
          const placeholders = ids.map(() => "?").join(",");
          const updateSql = `
            UPDATE ai_agent_memories 
            SET access_count = access_count + 1, last_accessed_at = ? 
            WHERE id IN (${placeholders})
          `;
          database_default.prepare(updateSql).run((/* @__PURE__ */ new Date()).toISOString(), ...ids);
        }
      }
      return results;
    } catch (err) {
      console.error("Error recalling memories:", err);
      return [];
    }
  }
  /**
   * Build memory context block for AI Prompt Augmentation
   */
  static buildMemoryContext(query2, userEmail = "system", entityId) {
    const recalled = this.recallMemories({
      query: query2,
      user_email: userEmail,
      entity_id: entityId,
      limit: 4,
      min_score: 0.3
    });
    if (!recalled || recalled.length === 0) {
      return "";
    }
    const lines = [
      "--- [B\u1ED8 NH\u1EDA D\xC0I H\u1EA0N & KINH NGHI\u1EC6M AI (TencentDB/Mem0 Agent Memory)] ---"
    ];
    for (const item of recalled) {
      const m = item.memory;
      lines.push(`\u2022 [${m.memory_type.toUpperCase()} | \u0110\u1ED9 quan tr\u1ECDng: ${(item.importanceScore * 100).toFixed(0)}%] ${m.title}: ${m.content}`);
    }
    lines.push("--- [H\u1EBET B\u1ED8 NH\u1EDA D\xC0I H\u1EA0N] ---\n");
    return lines.join("\n");
  }
  /**
   * Consolidate memories: Detect duplicates, consolidate reflections, remove obsolete data
   */
  static consolidateMemories() {
    try {
      const activeMemories = database_default.prepare("SELECT * FROM ai_agent_memories WHERE status = 'active' ORDER BY importance_score DESC").all();
      let consolidated = 0;
      let newReflections = 0;
      const byCategory = {};
      for (const m of activeMemories) {
        const cat = m.category || "general";
        if (!byCategory[cat]) byCategory[cat] = [];
        byCategory[cat].push(m);
      }
      for (const [cat, items] of Object.entries(byCategory)) {
        if (items.length >= 3) {
          const titles = items.map((i) => i.title).join("; ");
          const summarySynthesis = `H\u1EC7 th\u1ED1ng \u0111\xE3 \u0111\xFAc k\u1EBFt ${items.length} quy t\u1EAFc v\xE0 kinh nghi\u1EC7m trong danh m\u1EE5c '${cat}': G\u1ED3m ${titles}.`;
          const refTitle = `T\u1ED5ng h\u1EE3p kinh nghi\u1EC7m & Th\xF3i quen: ${cat.toUpperCase()}`;
          const existingRef = database_default.prepare("SELECT id FROM ai_memory_reflections WHERE reflection_title = ?").get(refTitle);
          if (!existingRef) {
            database_default.prepare(`
              INSERT INTO ai_memory_reflections (user_email, reflection_title, insights, source_memory_ids, created_at)
              VALUES (?, ?, ?, ?, ?)
            `).run(
              "system",
              refTitle,
              summarySynthesis,
              JSON.stringify(items.map((i) => i.id)),
              (/* @__PURE__ */ new Date()).toISOString()
            );
            newReflections++;
          }
          consolidated += items.length;
        }
      }
      return {
        consolidatedCount: consolidated,
        newReflections,
        message: `\u0110\xE3 ho\xE0n t\u1EA5t chu tr\xECnh h\u1EE3p nh\u1EA5t b\u1ED9 nh\u1EDB. \u0110\xE3 \u0111\xFAc k\u1EBFt ${newReflections} ph\xE2n t\xEDch t\u1ED5ng h\u1EE3p m\u1EDBi t\u1EEB ${consolidated} m\u1EA9u k\xFD \u1EE9c.`
      };
    } catch (err) {
      console.error("Error consolidating memories:", err);
      throw new Error(err.message || "Failed to consolidate memories.");
    }
  }
  /**
   * Get memory store statistics
   */
  static getStats() {
    try {
      const total = database_default.prepare("SELECT COUNT(*) as count FROM ai_agent_memories WHERE status = 'active'").get();
      const archived = database_default.prepare("SELECT COUNT(*) as count FROM ai_agent_memories WHERE status = 'archived'").get();
      const avgImp = database_default.prepare("SELECT AVG(importance_score) as avg FROM ai_agent_memories WHERE status = 'active'").get();
      const totalEntities = database_default.prepare("SELECT COUNT(*) as count FROM ai_memory_entities").get();
      const totalReflections = database_default.prepare("SELECT COUNT(*) as count FROM ai_memory_reflections").get();
      const typeDistribution = database_default.prepare(`
        SELECT memory_type, COUNT(*) as count 
        FROM ai_agent_memories 
        WHERE status = 'active' 
        GROUP BY memory_type
      `).all();
      return {
        total_active_memories: total?.count || 0,
        total_archived_memories: archived?.count || 0,
        average_importance: parseFloat((avgImp?.avg || 0.5).toFixed(2)),
        total_entities: totalEntities?.count || 0,
        total_reflections: totalReflections?.count || 0,
        type_distribution: typeDistribution,
        engine: "TencentDB-Agent-Memory / Mem0 Cognitive Engine for Legal OS"
      };
    } catch (err) {
      console.error("Error getting memory stats:", err);
      return {};
    }
  }
};

