function getAllCandidateAiProviders(taskType = "all", customApiKey, customProviderType) {
  const candidates = [];
  if (customApiKey && customApiKey.trim() !== "") {
    const cleanKey = customApiKey.trim();
    let providerType = customProviderType;
    if (!providerType) {
      if (cleanKey.startsWith("sk-or-")) providerType = "openrouter";
      else if (cleanKey.startsWith("sk-")) providerType = "openai";
      else providerType = "gemini";
    }
    const apiUrl = providerType === "openai" ? "https://api.openai.com/v1" : providerType === "claude" ? "https://api.anthropic.com/v1" : providerType === "deepseek" ? "https://api.deepseek.com/v1" : providerType === "openrouter" ? "https://openrouter.ai/api/v1" : "https://generativelanguage.googleapis.com";
    const defaultModel = providerType === "openai" ? "gpt-4o" : providerType === "claude" ? "claude-3-5-sonnet-20241022" : providerType === "deepseek" ? "deepseek-chat" : providerType === "openrouter" ? "google/gemini-2.5-flash" : "gemini-2.5-flash";
    candidates.push({
      id: -1,
      name: `User Custom (${providerType})`,
      provider_type: providerType,
      api_key: cleanKey,
      api_url: apiUrl,
      default_model: defaultModel,
      temperature: 0.2,
      max_tokens: 4096,
      is_active: 1
    });
    try {
      const exists = database_default.prepare("SELECT id FROM settings WHERE key = 'ai_api_key'").get();
      if (exists) {
        database_default.prepare("UPDATE settings SET value = ? WHERE key = 'ai_api_key'").run(cleanKey);
      } else {
        database_default.prepare("INSERT INTO settings (key, value) VALUES ('ai_api_key', ?)").run(cleanKey);
      }
      if (providerType) {
        const pExists = database_default.prepare("SELECT id FROM settings WHERE key = 'ai_provider'").get();
        if (pExists) {
          database_default.prepare("UPDATE settings SET value = ? WHERE key = 'ai_provider'").run(providerType);
        } else {
          database_default.prepare("INSERT INTO settings (key, value) VALUES ('ai_provider', ?)").run(providerType);
        }
      }
    } catch (e) {
    }
  }
  try {
    const activeProviders = database_default.prepare("SELECT * FROM ai_providers WHERE is_active = 1 ORDER BY id ASC").all();
    if (activeProviders && activeProviders.length > 0) {
      for (const p of activeProviders) {
        if (p.api_key && p.api_key.trim() !== "") {
          candidates.push(p);
        }
      }
    }
  } catch (e) {
    console.error("Error fetching ai_providers:", e);
  }
  try {
    const apiKeyRow = database_default.prepare("SELECT value FROM settings WHERE key = 'ai_api_key'").get();
    const modelRow = database_default.prepare("SELECT value FROM settings WHERE key = 'ai_model'").get();
    const providerRow = database_default.prepare("SELECT value FROM settings WHERE key = 'ai_provider'").get();
    if (apiKeyRow && apiKeyRow.value && apiKeyRow.value.trim() !== "") {
      const k = apiKeyRow.value.trim();
      if (!candidates.some((c) => c.api_key === k)) {
        const pType = providerRow?.value || (k.startsWith("sk-or-") ? "openrouter" : k.startsWith("sk-") ? "openai" : "gemini");
        candidates.push({
          id: 0,
          name: `Settings Key (${pType})`,
          provider_type: pType,
          api_key: k,
          api_url: pType === "openai" ? "https://api.openai.com/v1" : pType === "claude" ? "https://api.anthropic.com/v1" : pType === "openrouter" ? "https://openrouter.ai/api/v1" : "https://generativelanguage.googleapis.com",
          default_model: modelRow?.value || (pType === "openai" ? "gpt-4o" : pType === "openrouter" ? "google/gemini-2.5-flash" : "gemini-2.5-flash"),
          temperature: 0.2,
          max_tokens: 4096,
          is_active: 1
        });
      }
    }
  } catch (e) {
  }
  let defaultKey = process.env.GEMINI_API_KEY;
  if (defaultKey === "MY_GEMINI_API_KEY" || defaultKey === "dummy" || defaultKey === "your_api_key_here") {
    defaultKey = void 0;
  }
  if (defaultKey && !candidates.some((c) => c.api_key === defaultKey)) {
    candidates.push({
      id: 999,
      name: "Default Gemini",
      provider_type: "gemini",
      api_key: defaultKey,
      api_url: "https://generativelanguage.googleapis.com",
      default_model: "gemini-2.5-flash",
      temperature: 0.2,
      max_tokens: 4096,
      is_active: 1
    });
  }
  return candidates;
}
function getResolvedAiProvider(taskType = "all") {
  const candidates = getAllCandidateAiProviders(taskType);
  return candidates[0] || {
    id: 0,
    name: "Default Gemini",
    provider_type: "gemini",
    api_key: "",
    api_url: "https://generativelanguage.googleapis.com",
    default_model: "gemini-2.5-flash",
    temperature: 0.2,
    max_tokens: 4096,
    is_active: 1
  };
}
