router7.get("/land-documents", async (req, res) => {
  try {
    const { province_name, doc_type } = req.query;
    let query2 = "SELECT * FROM land_documents";
    const params = [];
    if (province_name || doc_type) {
      query2 += " WHERE";
      const conditions = [];
      if (province_name) {
        conditions.push(" province_name = ?");
        params.push(province_name);
      }
      if (doc_type) {
        conditions.push(" doc_type = ?");
        params.push(doc_type);
      }
      query2 += conditions.join(" AND");
    }
    query2 += " ORDER BY id DESC";
    const docs = database_default.prepare(query2).all(...params);
    res.json({ success: true, data: docs });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});
