var parseSalaryNumber = (val2) => {
  if (val2 === null || val2 === void 0) return 0;
  if (typeof val2 === "number") return val2;
  const str = String(val2).replace(/[^0-9]/g, "");
  return Number(str) || 0;
};
var calculatePayrollTaxes = (gross, dependents) => {
  const baseSalary = 234e4;
  const regionMinWage = 496e4;
  const bhxh_bhyt_cap = baseSalary * 20;
  const bhtn_cap = regionMinWage * 20;
  const bhxh_bhyt = Math.min(gross, bhxh_bhyt_cap) * 0.08 + Math.min(gross, bhxh_bhyt_cap) * 0.015;
  const bhtn = Math.min(gross, bhtn_cap) * 0.01;
  const insurance = Math.round(bhxh_bhyt + bhtn);
  const personalDeduction = 155e5;
  const dependentDeduction = 62e5 * dependents;
  const taxableIncome = gross - insurance - personalDeduction - dependentDeduction;
  let tax = 0;
  if (taxableIncome > 0) {
    if (taxableIncome <= 1e7) {
      tax = taxableIncome * 0.05;
    } else if (taxableIncome <= 3e7) {
      tax = taxableIncome * 0.1 - 5e5;
    } else if (taxableIncome <= 5e7) {
      tax = taxableIncome * 0.2 - 35e5;
    } else if (taxableIncome <= 8e7) {
      tax = taxableIncome * 0.28 - 75e5;
    } else {
      tax = taxableIncome * 0.35 - 131e5;
    }
  }
  return { insurance, tax: Math.round(tax) };
};
router8.get("/monthly-payrolls", auth2, (req, res) => {
  const { month, year } = req.query;
  const user = req.session.user;
  const mappedRole = mapRoleToDb(user.role);
  const p = database_default.prepare(`SELECT manageFinance FROM role_permissions WHERE role=?`).get(mappedRole);
  const hasAccess = p?.manageFinance || mappedRole === "admin" || mappedRole === "director";
  let dbPayrolls;
  if (hasAccess) {
    dbPayrolls = database_default.prepare(`
      SELECT p.*, u.name as user_name,
             COALESCE((SELECT SUM(bonus_amount) FROM evaluations e WHERE e.user_id = p.user_id AND e.month = p.month AND e.year = p.year AND e.target_type = 'personnel'), 0) as synced_bonus
      FROM monthly_payrolls p 
      JOIN users u ON p.user_id = u.id
      WHERE p.month = ? AND p.year = ?
    `).all(month, year);
  } else {
    dbPayrolls = database_default.prepare(`
      SELECT p.*, u.name as user_name,
             COALESCE((SELECT SUM(bonus_amount) FROM evaluations e WHERE e.user_id = p.user_id AND e.month = p.month AND e.year = p.year AND e.target_type = 'personnel'), 0) as synced_bonus
      FROM monthly_payrolls p 
      JOIN users u ON p.user_id = u.id
      WHERE p.month = ? AND p.year = ? AND p.user_id = ?
    `).all(month, year, user.id);
  }
  const allUsers = database_default.prepare(`SELECT id, name, role, title, branch, salary FROM users`).all();
  const enrichedUsers = enrichUsersWithStaffCode(allUsers);
  const targetUsers = enrichedUsers.filter((u) => {
    if (u.role === "client") return false;
    if (hasAccess) return true;
    return u.id === user.id;
  });
  const results = [];
  for (const u of targetUsers) {
    const existing = dbPayrolls.find((p2) => p2.user_id === u.id);
    const sumBonus = database_default.prepare(`SELECT SUM(bonus_amount) as s FROM evaluations WHERE user_id=? AND month=? AND year=? AND target_type='personnel'`).get(u.id, month, year)?.s || 0;
    if (existing) {
      existing.staff_code = u.staff_code;
      existing.title = u.title || u.role;
      existing.branch = u.branch || "";
      existing.user_name = u.name;
      const latestGross = parseSalaryNumber(u.salary) || existing.gross || 0;
      if (existing.gross !== latestGross) {
        existing.gross = latestGross;
      }
      existing.total_salary = (existing.gross || 0) + (existing.food_allowance || 0) + (existing.gas_allowance || 0) + (existing.phone_allowance || 0);
      existing.bonus = sumBonus;
      const calcs = calculatePayrollTaxes(existing.gross, existing.dependents || 0);
      existing.insurance = calcs.insurance;
      existing.tax = calcs.tax;
      existing.net = existing.total_salary + (existing.other_benefits || 0) + existing.bonus - (existing.violations || 0) - (existing.insurance || 0) - (existing.tax || 0);
      database_default.prepare(`UPDATE monthly_payrolls SET staff_code=?, title=?, branch=?, gross=?, insurance=?, tax=?, total_salary=?, bonus=?, net=? WHERE id=?`).run(
        existing.staff_code,
        existing.title,
        existing.branch,
        existing.gross,
        existing.insurance,
        existing.tax,
        existing.total_salary,
        existing.bonus,
        existing.net,
        existing.id
      );
      results.push(existing);
    } else {
      const grossVal = parseSalaryNumber(u.salary) || 0;
      const calcs = calculatePayrollTaxes(grossVal, 0);
      const totalSalary = grossVal;
      const netVal = totalSalary + sumBonus - calcs.insurance - calcs.tax;
      const defaultP = {
        id: -u.id,
        user_id: u.id,
        month: Number(month),
        year: Number(year),
        staff_code: u.staff_code,
        title: u.title || u.role,
        branch: u.branch || "",
        working_days: 26,
        dependents: 0,
        gross: grossVal,
        insurance: calcs.insurance,
        tax: calcs.tax,
        net: netVal,
        food_allowance: 0,
        gas_allowance: 0,
        phone_allowance: 0,
        other_benefits: 0,
        bonus: sumBonus,
        violations: 0,
        total_salary: totalSalary,
        user_name: u.name,
        synced_bonus: sumBonus
      };
      results.push(defaultP);
    }
  }
  results.sort((a, b) => {
    const numA = Number((a.staff_code || "").match(/\d+$/)?.[0] || 999);
    const numB = Number((b.staff_code || "").match(/\d+$/)?.[0] || 999);
    return numA - numB;
  });
  res.json(results);
});
