        { stage: "CASE", label: "V\u1EE5 vi\u1EC7c / H\u1EE3p \u0111\u1ED3ng", count: casesCountRow?.count || Math.round(funnelConsultations * 0.3), pct: funnelCalls > 0 ? Math.round((casesCountRow?.count || funnelConsultations * 0.3) / funnelCalls * 100) : 0 }
