var PaymentWorkflowEngine = class {
  constructor() {
    this.validTransitions = {
      ["Draft" /* Draft */]: ["QR Generated" /* QrGenerated */, "Waiting Payment" /* WaitingPayment */, "Cancelled" /* Cancelled */],
      ["QR Generated" /* QrGenerated */]: ["Waiting Payment" /* WaitingPayment */, "Money Received" /* MoneyReceived */, "Cancelled" /* Cancelled */],
      ["Waiting Payment" /* WaitingPayment */]: ["Money Received" /* MoneyReceived */, "AI Reconciliation" /* AiReconciliation */, "Cancelled" /* Cancelled */],
      ["Money Received" /* MoneyReceived */]: ["AI Reconciliation" /* AiReconciliation */, "Finance Approved" /* FinanceApproved */],
      ["AI Reconciliation" /* AiReconciliation */]: ["Finance Approved" /* FinanceApproved */, "Receipt Created" /* ReceiptCreated */],
      ["Finance Approved" /* FinanceApproved */]: ["Receipt Created" /* ReceiptCreated */, "Completed" /* Completed */],
      ["Receipt Created" /* ReceiptCreated */]: ["Completed" /* Completed */],
      ["Completed" /* Completed */]: [],
      ["Cancelled" /* Cancelled */]: ["Draft" /* Draft */]
    };
  }
  canTransition(currentState, nextState) {
    const allowed = this.validTransitions[currentState] || [];
    return allowed.includes(nextState);
  }
  getNextState(currentState) {
    const allowed = this.validTransitions[currentState] || [];
    return allowed[0] || null;
  }
};
