router16.get("/attendance", auth2, (req, res) => {
  try {
    const { date, month, year, employee_id } = req.query;
    const limit2 = req.query.limit ? Math.min(100, Math.max(1, parseInt(req.query.limit) || 20)) : null;
    const cursorStr = req.query.cursor;
    let query2 = "SELECT a.*, u.name as employee_name, u.staff_code FROM hr_attendance a JOIN users u ON a.employee_id = CAST(u.id AS TEXT) WHERE 1=1";
    const params = {};
    if (date) {
      query2 += " AND a.date = :date";
      params.date = date;
    }
    if (month && year) {
      query2 += " AND a.date LIKE :monthPattern";
      params.monthPattern = `${year}-${String(month).padStart(2, "0")}%`;
    }
    if (employee_id) {
      query2 += " AND a.employee_id = :employee_id";
      params.employee_id = String(employee_id);
    }
    if (limit2 !== null) {
      if (cursorStr) {
        const cursor = decodeCursor(cursorStr);
        if (cursor && cursor.date && cursor.id) {
          query2 += " AND (a.date < :cursorDate OR (a.date = :cursorDate AND a.id < :cursorId))";
          params.cursorDate = cursor.date;
          params.cursorId = cursor.id;
        }
      }
      query2 += " ORDER BY a.date DESC, a.id DESC LIMIT :limitPlusOne";
      params.limitPlusOne = limit2 + 1;
      const rows = database_default.prepare(query2).all(params);
      const hasNextPage = rows.length > limit2;
      const returnedRows = hasNextPage ? rows.slice(0, limit2) : rows;
      let nextCursor = null;
      if (hasNextPage && returnedRows.length > 0) {
        const lastRow = returnedRows[returnedRows.length - 1];
        nextCursor = encodeCursor({ date: lastRow.date, id: lastRow.id });
      }
      res.json({
        success: true,
        data: returnedRows,
        pagination: {
          limit: limit2,
          nextCursor,
          hasNextPage
        }
      });
    } else {
      query2 += " ORDER BY a.date DESC, a.check_in ASC";
      const rows = database_default.prepare(query2).all(params);
      res.json({ success: true, data: rows });
    }
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});
router16.post("/attendance/check-in-out", auth2, (req, res) => {
  try {
    const { employee_id, date, time, method, gps, ip, device_id, photo, type } = req.body;
    const today = date || (/* @__PURE__ */ new Date()).toISOString().split("T")[0];
    const nowTime = time || (/* @__PURE__ */ new Date()).toTimeString().split(" ")[0].substring(0, 5);
    const empIdStr = String(employee_id || req.session.user?.id);
    const existing = database_default.prepare("SELECT * FROM hr_attendance WHERE employee_id = ? AND date = ?").get(empIdStr, today);
    let aiWarning = "";
    if (method === "GPS" && gps) {
      const [lat, lng] = String(gps).split(",").map(Number);
      if (lat && lng && (Math.abs(lat - 10.776) > 0.05 || Math.abs(lng - 106.7) > 0.05)) {
        aiWarning = "C\u1EA3nh b\xE1o GPS: V\u1ECB tr\xED ch\u1EA5m c\xF4ng xa tr\u1EE5 s\u1EDF ch\xEDnh qu\xE1 5km!";
      }
    }
    if (!existing) {
      const lateMins = nowTime > "08:00" ? Math.round(((/* @__PURE__ */ new Date(`1970-01-01T${nowTime}:00`)).getTime() - (/* @__PURE__ */ new Date("1970-01-01T08:00:00")).getTime()) / 6e4) : 0;
      const id = `ATT-${Date.now()}`;
      database_default.prepare(`
        INSERT INTO hr_attendance (id, employee_id, date, check_in, working_hours, late_minutes, device_id, attendance_method, gps, ip, photo, status, ai_warning)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(id, empIdStr, today, nowTime, 0, Math.max(0, lateMins), device_id || "MOBILE-APP", method || "Mobile App", gps || "", ip || req.ip, photo || "", "Present", aiWarning);
      res.json({ success: true, action: "CHECK_IN", time: nowTime, late_minutes: Math.max(0, lateMins), aiWarning });
    } else {
      let workingHours = 8;
      if (existing.check_in) {
        const inMs = (/* @__PURE__ */ new Date(`1970-01-01T${existing.check_in}:00`)).getTime();
        const outMs = (/* @__PURE__ */ new Date(`1970-01-01T${nowTime}:00`)).getTime();
        workingHours = Math.max(0, Math.round((outMs - inMs) / 36e5 * 10) / 10);
      }
      const earlyLeave = nowTime < "17:00" ? Math.round(((/* @__PURE__ */ new Date("1970-01-01T17:00:00")).getTime() - (/* @__PURE__ */ new Date(`1970-01-01T${nowTime}:00`)).getTime()) / 6e4) : 0;
      database_default.prepare(`
        UPDATE hr_attendance 
        SET check_out = ?, working_hours = ?, early_leave = ?, ai_warning = COALESCE(ai_warning, '') || ?
        WHERE id = ?
      `).run(nowTime, workingHours, Math.max(0, earlyLeave), aiWarning ? ` | ${aiWarning}` : "", existing.id);
      res.json({ success: true, action: "CHECK_OUT", time: nowTime, working_hours: workingHours, early_leave: Math.max(0, earlyLeave) });
    }
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});
