var validateDeviceApiKey = (req, res, next) => {
  const { device_id } = req.body;
  const apiKey = req.headers["x-api-key"] || req.query.api_key || req.body.api_key;
  if (!device_id) {
    return res.status(400).json({ success: false, message: "Thi\u1EBFu device_id" });
  }
  try {
    const device = database_default.prepare("SELECT api_key FROM iot_devices WHERE id = ?").get(device_id);
    if (!device) {
      return res.status(404).json({ success: false, message: "Thi\u1EBFt b\u1ECB ch\u01B0a \u0111\u01B0\u1EE3c \u0111\u0103ng k\xFD trong h\u1EC7 th\u1ED1ng" });
    }
    if (!apiKey || apiKey !== device.api_key) {
      return res.status(401).json({ success: false, message: "X\xE1c th\u1EF1c thi\u1EBFt b\u1ECB th\u1EA5t b\u1EA1i: API Key kh\xF4ng \u0111\xFAng ho\u1EB7c b\u1ECB t\u1EEB ch\u1ED1i" });
    }
    next();
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
};
database_default.exec(`
  CREATE TABLE IF NOT EXISTS iot_devices (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    mac_address TEXT,
    ip_address TEXT,
    location TEXT,
    device_type TEXT NOT NULL, -- 'esp32_cam', 'weather_station', 'rfid_reader', 'led_display'
    status TEXT DEFAULT 'online', -- 'online', 'offline', 'warning'
    last_seen DATETIME DEFAULT CURRENT_TIMESTAMP,
    api_key TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS iot_telemetry (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    device_id TEXT NOT NULL,
    temperature REAL,
    humidity REAL,
    air_quality INTEGER,
    pressure REAL,
    weather_condition TEXT,
    raw_payload TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS iot_attendance_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    device_id TEXT NOT NULL,
    employee_id TEXT,
    employee_name TEXT,
    method TEXT DEFAULT 'face_id', -- 'face_id', 'rfid', 'fingerprint'
    confidence REAL,
    snapshot_url TEXT,
    status TEXT DEFAULT 'success',
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS iot_rules (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    triggerDevice TEXT NOT NULL,
    triggerParam TEXT NOT NULL,
    operator TEXT NOT NULL,
    triggerValue TEXT NOT NULL,
    actionDevice TEXT NOT NULL,
    actionCommand TEXT NOT NULL,
    active INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS iot_alerts (
    id TEXT PRIMARY KEY,
    time TEXT NOT NULL,
    title TEXT NOT NULL,
    location TEXT NOT NULL,
    severity TEXT NOT NULL, -- 'critical', 'warning', 'info', 'resolved'
    status TEXT NOT NULL, -- 'active', 'muted', 'resolved'
    details TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`);
