var evaluateRules = (deviceId, triggerParam, value) => {
  try {
    const rules = database_default.prepare("SELECT * FROM iot_rules WHERE triggerDevice = ? AND triggerParam = ? AND active = 1").all();
    for (const rule of rules) {
      let triggered = false;
      const valNum = parseFloat(value);
      const trigNum = parseFloat(rule.triggerValue);
      if (rule.operator === "=") {
        triggered = value.toString() === rule.triggerValue.toString();
      } else if (rule.operator === ">" && !isNaN(valNum) && !isNaN(trigNum)) {
        triggered = valNum > trigNum;
      } else if (rule.operator === "<" && !isNaN(valNum) && !isNaN(trigNum)) {
        triggered = valNum < trigNum;
      } else if (rule.operator === "changes") {
        triggered = true;
      }
      if (triggered) {
        const timeStr = (/* @__PURE__ */ new Date()).toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit", hour12: true });
        const alertId = `EXEC-${rule.id}-${Date.now().toString().slice(-4)}`;
        const details = `Thi\u1EBFt b\u1ECB ${rule.triggerDevice} k\xEDch ho\u1EA1t h\xE0nh \u0111\u1ED9ng [${rule.actionCommand}] tr\xEAn thi\u1EBFt b\u1ECB \u0111\xEDch ${rule.actionDevice}.`;
        database_default.prepare(`
          INSERT INTO iot_alerts (id, time, title, location, severity, status, details)
          VALUES (?, ?, ?, ?, ?, ?, ?)
        `).run(
          alertId,
          timeStr,
          `[AUTOMATION ENFORCED] ${rule.name}`,
          rule.actionDevice,
          "resolved",
          "resolved",
          details
        );
        console.log(`[AUTOMATION] Triggered rule ${rule.id}: ${rule.name}`);
      }
    }
  } catch (err) {
    console.error("Error evaluating rules:", err);
  }
};
